-- agv-precision-pty-ltd-blue-valley-golf-estate (researched)
UPDATE businesses SET description = 'AGV Precision (Pty) Ltd is a precision engineering and special purpose machinery manufacturer based at Corporate Park, 20 Victoria Link, Route 21, in Irene, Pretoria. The company was founded in 1990 to assist industry through the manufacture of high-precision parts, and its wire erosion and precision engineering work has since served a wide range of sectors, including paper, marine, textile, leather, printing, motor, arms, medical, chemical and food industries. Operating as a jobbing shop rather than a single-product manufacturer, AGV Precision takes on precision machining and tooling work across these varied industries, relying on its wire erosion capability to achieve the fine tolerances that this kind of work demands. Having operated from Irene since 1990, the company has built up more than three decades of manufacturing experience across sectors with very different material and tolerance requirements, giving it a broad base of technical know-how to draw on for new precision engineering projects brought to it by industrial clients.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://agvprecision.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'agv-precision-pty-ltd-blue-valley-golf-estate' AND description = 'AGV Precision is a precision engineering jobbing shop in Irene offering wire erosion, tool making, prototyping and high-precision machining to ISO 9000:2008 standards.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- alice-in-waterkloof-waterkloof (researched)
UPDATE businesses SET description = 'Alice in Waterkloof is a family-owned garden restaurant on Milner Street in Waterkloof, Pretoria, built around what it calls a secret garden escape from the area''s more conventional dining options. The restaurant has operated for 12 years, seats around 50 guests, and makes its menu fresh daily rather than relying on reheated or mass-produced dishes. It focuses on breakfast and light lunch service in a peaceful, garden setting designed to slow guests down, positioning itself against the loud, rushed atmosphere of typical restaurants. Its food is prepared without shortcuts, with the kitchen team drawing on formal culinary training and experience gained at some of South Africa''s top restaurants before joining Alice. Being family-run gives the restaurant a personal, consistent approach to service, with the family having a long-standing connection to the Waterkloof area. For visitors wanting a quiet, unhurried meal away from Pretoria''s busier restaurant strips, Alice in Waterkloof offers an intimate, garden-based alternative within easy reach of the surrounding Waterkloof and Brooklyn suburbs.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://aliceinwaterkloof.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'alice-in-waterkloof-waterkloof' AND description = 'Alice in Waterkloof is a garden restaurant and cafe on Milner Street in Waterkloof, serving breakfast and light lunches in a secluded garden setting.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
